/**
 * What the JavaScript on a page is actually made of.
 *
 * Turbopack ships one page as thirty-odd hashed chunks, so a chunk list tells
 * you nothing. This opens each page in a real Chrome, records every script the
 * browser fetched and how many bytes came over the wire, then reads the source
 * map beside each chunk and attributes the generated bytes back to the package
 * or app folder they came from. The result is the ten heaviest things on a
 * route, by name.
 *
 * The maps are only written when the build asks for them:
 *
 *   ANALYZE=1 NEXT_DIST_DIR=.next-check npx next build
 *   NEXT_DIST_DIR=.next-check npx next start -p 3311
 *   node packages/web/scripts/perf/bundle.mjs --base http://localhost:3311 --dist .next-check
 *
 * Options: --base, --dist, --paths, --out, --top, --browser, --port.
 */

import { spawn, spawnSync } from "node:child_process";
import { mkdtemp, readFile, rm, writeFile } from "node:fs/promises";
import { existsSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";

/** base64 for the VLQ digits in a source map. */
const ALPHABET = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";

const PASSPORT = "0xcdb25d3755452efa3b746f168cf9cefd3a1b693ab2b81d260a2d64f13d771638";

const DEFAULT_PATHS = [
  "/en",
  "/en/verify",
  "/en/studio",
  "/en/explore",
  `/en/passport/${PASSPORT}`,
  "/en/agent/10249",
  "/en/docs",
  "/en/docs/how-it-works/architecture",
];

const CHROMES = [
  process.env.CHROME,
  "chrome-headless-shell",
  "C:/Program Files/Google/Chrome/Application/chrome.exe",
  "C:/Program Files (x86)/Google/Chrome/Application/chrome.exe",
  "/usr/bin/google-chrome",
];

let nextId = 1;
const waiting = new Map();
let socket;

const args = readArgs(process.argv.slice(2));
const base = (args.base ?? "http://localhost:3311").replace(/\/$/, "");
const dist = args.dist ?? ".next-perf";
const top = Number(args.top ?? 10);
const port = Number(args.port ?? 9444);
const paths = args.paths === undefined || args.paths === "" ? DEFAULT_PATHS : args.paths.split(",");

const browser =
  args.browser ?? CHROMES.find((path) => path !== undefined && (path.includes("/") ? existsSync(path) : onPath(path)));
if (browser === undefined) {
  throw new Error("no browser found: pass --browser with the path to Chrome");
}

const root = join(process.cwd(), "packages", "web");
const chunkCache = new Map();
const lines = [];
const say = (line) => {
  lines.push(line);
  console.log(line);
};

const profile = await mkdtemp(join(tmpdir(), "moolam-bundle-"));
const child = spawn(
  browser,
  [
    "--headless=new",
    `--remote-debugging-port=${port}`,
    `--user-data-dir=${profile}`,
    "--window-size=1440,900",
    "--no-first-run",
    "--no-default-browser-check",
    "--disable-extensions",
    "--disable-gpu",
    "about:blank",
  ],
  { stdio: "ignore" },
);

try {
  socket = await open(await waitForTarget());
  await send("Page.enable");
  await send("Network.enable");
  await send("Runtime.enable");

  for (const path of paths) {
    const scripts = await load(`${base}${path}`);
    const wire = scripts.reduce((total, one) => total + one.bytes, 0);
    const owners = new Map();
    for (const script of scripts) {
      const map = await modulesOf(script.url);
      if (map.total === 0) {
        owners.set("(no source map)", (owners.get("(no source map)") ?? 0) + script.bytes);
        continue;
      }
      // The source map measures the unzipped chunk, so each module's share of
      // its chunk is turned back into wire bytes by the same ratio.
      const ratio = script.bytes / map.total;
      for (const [name, bytes] of map.owners) {
        owners.set(name, (owners.get(name) ?? 0) + bytes * ratio);
      }
    }

    say("");
    say(`${path}    ${scripts.length} scripts    ${kb(wire)} kB over the wire`);
    for (const [name, bytes] of [...owners.entries()].sort((a, b) => b[1] - a[1]).slice(0, top)) {
      say(`  ${pad(kb(bytes), 8)} kB  ${name}`);
    }
  }

  if (args.out !== undefined && args.out !== "") {
    await writeFile(args.out, `${lines.join("\n")}\n`, "utf8");
  }
} finally {
  socket?.close();
  child.kill();
  await rm(profile, { recursive: true, force: true }).catch(() => undefined);
}

/** Opens a page and returns every script the browser fetched, with its wire bytes. */
async function load(url) {
  const seen = new Map();
  const byRequest = new Map();
  const onMessage = (event) => {
    const message = JSON.parse(event.data);
    if (message.method === "Network.responseReceived" && message.params.type === "Script") {
      byRequest.set(message.params.requestId, message.params.response.url);
    }
    if (message.method === "Network.loadingFinished") {
      const scriptUrl = byRequest.get(message.params.requestId);
      if (scriptUrl !== undefined) {
        seen.set(scriptUrl, message.params.encodedDataLength);
      }
    }
  };
  socket.addEventListener("message", onMessage);
  try {
    await send("Network.clearBrowserCache");
    await send("Page.navigate", { url });
    await wait(9000);
    // The film and the drawings arrive after the first paint, so the page is
    // scrolled once and given a moment before the list is closed.
    await evaluate("window.scrollTo(0, document.body.scrollHeight / 2)");
    await wait(4000);
  } finally {
    socket.removeEventListener("message", onMessage);
  }
  return [...seen.entries()].map(([scriptUrl, bytes]) => ({ url: scriptUrl, bytes }));
}

/** Generated bytes per owning package or app folder for one chunk, read from its map. */
async function modulesOf(url) {
  const name = new URL(url).pathname;
  if (chunkCache.has(name)) {
    return chunkCache.get(name);
  }
  const answer = { total: 0, owners: new Map() };
  const file = join(root, dist, name.replace(/^\/_next\//, ""));
  if (existsSync(file)) {
    const code = await readFile(file, "utf8");
    // Turbopack does not name a map after its chunk, so the only way to find it
    // is the comment the chunk ends with.
    const named = code.match(/\/\/# sourceMappingURL=(\S+)\s*$/);
    const map = named === null ? null : join(file, "..", named[1]);
    if (map !== null && existsSync(map)) {
      attribute(JSON.parse(await readFile(map, "utf8")), code, answer);
    }
  }
  chunkCache.set(name, answer);
  return answer;
}

function attribute(map, code, answer) {
  const lengths = code.split("\n").map((line) => line.length + 1);
  const sources = (map.sources ?? []).map(owner);
  let sourceIndex = 0;
  let line = 0;
  for (const group of (map.mappings ?? "").split(";")) {
    let column = 0;
    let previous = null;
    for (const segment of group.split(",")) {
      if (segment === "") {
        continue;
      }
      const fields = decode(segment);
      column += fields[0];
      if (fields.length >= 4) {
        sourceIndex += fields[1];
      }
      if (previous !== null) {
        add(answer, previous.owner, column - previous.column);
      }
      previous = { column, owner: fields.length >= 4 ? sources[sourceIndex] : null };
    }
    if (previous !== null) {
      add(answer, previous.owner, Math.max(0, (lengths[line] ?? 0) - previous.column));
    }
    line += 1;
  }
}

function add(answer, name, bytes) {
  if (name === undefined || name === null || bytes <= 0) {
    return;
  }
  answer.total += bytes;
  answer.owners.set(name, (answer.owners.get(name) ?? 0) + bytes);
}

/** A source path turned into the name a reader would recognise. */
function owner(source) {
  const clean = String(source)
    .replace(/\\/g, "/")
    .replace(/^turbopack:\/\/\/?/, "")
    .replace(/\?.*$/, "");
  const parts = clean.split("node_modules/");
  if (parts.length > 1) {
    const rest = parts[parts.length - 1].split("/");
    return rest[0].startsWith("@") ? `${rest[0]}/${rest[1]}` : rest[0];
  }
  const app = clean.match(/(?:packages\/web\/)?((?:app|components|lib|styles|messages)\/.*)$/);
  if (app !== null) {
    const bits = app[1].split("/");
    return bits.slice(0, Math.min(3, bits.length)).join("/");
  }
  return clean.split("/").slice(-2).join("/");
}

function decode(segment) {
  const out = [];
  let shift = 0;
  let value = 0;
  for (const character of segment) {
    const digit = ALPHABET.indexOf(character);
    if (digit === -1) {
      return out;
    }
    const more = (digit & 32) !== 0;
    value += (digit & 31) << shift;
    if (more) {
      shift += 5;
      continue;
    }
    const negative = (value & 1) === 1;
    value >>= 1;
    out.push(negative ? -value : value);
    shift = 0;
    value = 0;
  }
  return out;
}

function kb(bytes) {
  return Math.round(bytes / 1024);
}

function pad(value, width) {
  const text = String(value);
  return text.length >= width ? text : " ".repeat(width - text.length) + text;
}

function onPath(name) {
  return spawnSync(process.platform === "win32" ? "where" : "which", [name], { stdio: "ignore" }).status === 0;
}

function readArgs(list) {
  const out = {};
  for (let index = 0; index < list.length; index += 1) {
    if (!list[index].startsWith("--")) {
      continue;
    }
    const next = list[index + 1];
    out[list[index].slice(2)] = next === undefined || next.startsWith("--") ? "" : next;
  }
  return out;
}

function wait(ms) {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

async function waitForTarget() {
  for (let attempt = 0; attempt < 100; attempt += 1) {
    try {
      const response = await fetch(`http://127.0.0.1:${port}/json/list`);
      const page = (await response.json()).find((entry) => entry.type === "page");
      if (page !== undefined) {
        return page.webSocketDebuggerUrl;
      }
    } catch {
      // The browser has not opened its port yet.
    }
    await wait(100);
  }
  throw new Error("the browser never opened its debugging port");
}

function open(target) {
  return new Promise((resolve, reject) => {
    const connection = new WebSocket(target);
    connection.addEventListener("open", () => resolve(connection));
    connection.addEventListener("error", reject);
    connection.addEventListener("message", (event) => {
      const message = JSON.parse(event.data);
      const pending = waiting.get(message.id);
      if (pending !== undefined) {
        waiting.delete(message.id);
        if (message.error === undefined) {
          pending.resolve(message.result);
        } else {
          pending.reject(new Error(message.error.message));
        }
      }
    });
  });
}

function send(method, params = {}) {
  const id = nextId;
  nextId += 1;
  return new Promise((resolve, reject) => {
    waiting.set(id, { resolve, reject });
    socket.send(JSON.stringify({ id, method, params }));
  });
}

async function evaluate(expression) {
  const answer = await send("Runtime.evaluate", { expression, returnByValue: true, awaitPromise: true });
  return answer.result?.value;
}
